-- ============================================
-- CRYBE · Seed inicial (datos actuales del sitio)
-- Ejecutar DESPUÉS de schema.sql
-- ============================================

-- ESPECIALIDADES
on conflict (slug) do update set nombre = excluded.nombre, titulo = excluded.titulo, descripcion = excluded.descripcion, imagen = excluded.imagen;

-- PROFESIONALES
on conflict (slug) do update set nombre = excluded.nombre, foto_url = excluded.foto_url, descripcion = excluded.descripcion, whatsapp = excluded.whatsapp;

-- NOVEDADES
on conflict (slug) do update set titulo = excluded.titulo, descripcion = excluded.descripcion, cuerpo = excluded.cuerpo;
