insert into especialidades (slug, nombre, titulo, descripcion, imagen) values
('psicologia', 'Psicología', 'Entender tus emociones es el primer paso para transformarlas.', 'Acompañamiento psicológico desde una mirada cercana, profesional e integral.', '/psicologia.webp'),
('psiquiatria', 'Psiquiatría', 'Un espacio donde tu bienestar también encuentra lugar.', 'Atención especializada orientada al cuidado de la salud mental y el bienestar emocional.', '/psiquiatria.jpg'),
('fonoaudiologia', 'Fonoaudiología', 'Cuando se abre la puerta a la comunicación todo es posible.', 'Acompañamos los procesos relacionados con el lenguaje, el habla y la comunicación.', '/fonoaudiologia.webp'),
('psicopedagogia', 'Psicopedagogía', 'El aprendizaje es un proceso que dura toda la vida.', 'Acompañamos los procesos de aprendizaje respetando los tiempos, necesidades y fortalezas de cada persona.', '/psicopedagogia.avif'),
('kinesiologia-psicomotricidad', 'Kinesiología y Psicomotricidad', 'Tu cuerpo tiene su propio ritmo, nosotros acompañamos cada etapa.', 'Acompañamos el desarrollo motor y corporal desde una mirada integral y personalizada.', '/Kinesiologia.webp')
insert into profesionales (slug, nombre, especialidad, especialidad_slug, modalidad, foto_url, matricula, resumen, descripcion, whatsapp, dias, horarios, mostrar_horarios, areas, activo, orden) values
('pamela-garrido', 'Lic. Pamela Garrido', 'Psicología', 'psicologia', 'Atención presencial', '/Garrido.png', 'MP 0000', 'Acompañamiento psicológico desde una mirada integral y personalizada.', 'Clinica de Niños, Adolescentes y Adultos. Psicoterapia Integrativa Cognitivo Conductual.', '549XXXXXXXXXX', array['Lunes','Miércoles','Viernes'], '14:00 a 19:00', true, '{}', true, 1),
('helga-ticac', 'Dra. Helga Ticac', 'Psicología', 'psicologia', 'Atención presencial', '/Ticac.png', 'MP 0000', 'Espacio de acompañamiento emocional para niños, adolescentes y adultos.', 'Clínica de niños, adolescentes, adultos y familias. Psicoterapia individual y grupal. Formación cognitivo conductual y sistémica.', '549XXXXXXXXXX', array['Martes','Jueves'], '15:00 a 20:00', true, array['Doctora en Psicología (Universidad Nacional de La Plata)','Magister en problemas y patologías del desvalimiento (UCES)','Licenciada en Psicología (UFLO)','Licenciada en Servicio Social (UNC)','Diplomatura en gerencia social y políticas de la discapacidad (FLACSO)'], true, 2),
('juan-pablo-bourre', 'Dr. Juan Pablo Bourre', 'Psiquiatría', 'psiquiatria', 'Atención presencial y online', '/Bourre.png', 'MP 0000', 'Atención especializada para el cuidado integral de la salud mental.', 'Médico Psiquiatra formado en el Hospital Argerich y Moyano de la Ciudad Autónoma de Buenos Aires. Orientado a un abordaje integral de la salud mental.', '549XXXXXXXXXX', array['Miércoles','Viernes'], '16:00 a 20:00', true, '{}', true, 3),
('julieta-cayul', 'Lic. Julieta Cayul', 'Fonoaudiología', 'fonoaudiologia', 'Atención presencial', '/Cayul.png', 'MP 0000', 'Acompañamiento en lenguaje, habla, voz y comunicación.', 'Licenciada en Fonoaudiología, formada en Córdoba. 10 años de experiencia clínica con niños, adolescentes y adultos en Neurofonoaudiología, Lenguaje y Deglución.', '549XXXXXXXXXX', array['Lunes','Jueves'], '14:00 a 18:00', true, array['Residencia en Neurofonoaudiología','Posgrado en Clínica del Lenguaje','Formación en Fonoestomatología','Formación en Fonoaudiología Crítica'], true, 4),
('estefani-salaya', 'Lic. Estefani Salaya', 'Psicopedagogía', 'psicopedagogia', 'Atención presencial', '/Salaya.png', 'MP 0000', 'Acompañamiento de procesos de aprendizaje respetando cada recorrido.', 'Clínica de Niños, Adolescentes y adultos con desafíos en el desarrollo.', '549XXXXXXXXXX', array['Martes','Jueves','Viernes'], '13:00 a 18:00', true, array['Diplomada en prácticas inclusivas en condición del espectro autista (FACSO)','Certificada en DIR Floortime Nivel I','Certificada en ADOS-2','Especialista en prácticas basadas en experiencia Nivel I'], true, 5),
('paula-vega', 'Lic. Paula Vega', 'Psicología', 'psicologia', 'Atención presencial', '/Vega.png', 'MP RN 2770', 'Clínica de Niños, Adolescentes y Adultos. Terapia Cognitivo Conductual.', 'Clínica de Niños, Adolescentes y Adultos. Psicotécnicos y Psicodiagnósticos. Terapia Cognitivo Conductual.', '549XXXXXXXXXX', '{}', '', false, array['Licenciada en Psicología de la Facultad de Flores','Diplomada en Terapia Cognitivo Conductual en Niños y Adolescentes','Diplomada en Psico Grafología Forense','Diplomada en Psicodiagnóstico (Universidad del Aconcagua)'], true, 6),
('susana-lopez-baez', 'Lic. Susana Lopez Baez', 'Psicopedagogía', 'psicopedagogia', 'Atención presencial', '/Baez.png', 'MP 0000', 'Acompañamiento de procesos de aprendizaje respetando cada recorrido.', 'Clínica de niños, adolescentes y adultos.', '549XXXXXXXXXX', '{}', '', false, array['Licenciada en Psicopedagogía (Universidad del Gran Rosario)','Maestranda en Neuropsicología Infantil (UNSAM)','Diploma Superior en prácticas inclusivas (FLACSO)','Diplomatura Superior en Neuropsicología Clínica (UNAJ)'], true, 7),
('lucia-del-castillo', 'Lucía del Castillo', 'Psicopedagogía', 'psicopedagogia', 'Atención presencial', '/Castillo.jpeg', 'MP 0000', 'Acompañamiento de procesos de aprendizaje respetando cada recorrido.', 'Clínica de Niños, Adolescentes y adultos. Discapacidad, dificultades específicas de aprendizaje y habilidades de la vida diaria.', '549XXXXXXXXXX', '{}', '', false, array['Nivel I en Lengua de Señas Argentina','Diplomatura en Discapacidad','Formación en TCC (Academia Walden)'], true, 8),
('camila-mussi-saluj', 'Camila Mussi Saluj', 'Kinesiología y Psicomotricidad', 'kinesiologia-psicomotricidad', 'Atención presencial', '/Saluj.png', 'MP 0000', 'Acompañamiento del desarrollo motor y corporal desde una mirada integral.', 'Kinesiología y psicomotricidad: desarrollo motor y corporal integral.', '549XXXXXXXXXX', '{}', '', false, '{}', true, 9)
insert into novedades (slug, categoria, titulo, descripcion, cuerpo, imagen_principal, galeria, autor) values
('caricaturas-recomendadas', 'Psicopedagogía', 'Caricaturas recomendadas', 'No todas las caricaturas son malas: estas cuatro enseñan sin gritar y abren conversaciones en casa.', array['Papás, ojo: no todas las caricaturas son malas. Estas cuatro sí aportan: enseñan sin gritar, acompañan sin sobreestimular y abren conversaciones.','Si eligen usar pantallas, que sea con criterio: momentos acotados, contenido elegido y, siempre que se pueda, mirando juntos para conversar después.','Ningún dibujo va a educar a tus hijos por ti, pero algunos pueden ayudarte a que el aprendizaje fluya más fácil.'], '/dibujos1.png', array['/dibujos2.png','/dibujos3.png','/dibujos4.png','/dibujos5.png','/dibujos6.png'], 'Equipo CRyBE'),
('ir-a-terapia', 'Psicología', '¿Ir a terapia?', 'Comenzar terapia es decidir enfrentar lo que te hace mal con acompañamiento profesional.', array['Comenzar terapia es tomar la decisión de enfrentarte a lo que te está haciendo mal, pero con acompañamiento profesional y herramientas efectivas.','En CRyBE trabajamos con enfoque basado en evidencia, como la Terapia Cognitivo Conductual.','No hace falta tener todo claro para empezar. A veces, el primer paso es simplemente empezar a hablar.'], '/terapia1.png', array['/terapia2.png','/terapia3.png','/terapia4.png'], 'Equipo CRyBE'),
('cuando-consultar-psicopedagogo', 'Psicopedagogía', '¿Cómo saber cuándo consultar con un psicopedagogo?', 'Signos de alerta en la etapa escolar: lectoescritura, atención y frustración.', array['Cada niño tiene su propio ritmo, pero hay señales: dificultad persistente con letras o sonidos, rechazo a leer en voz alta, problemas para seguir instrucciones o frustración desproporcionada.','Una evaluación a tiempo permite identificar el origen y diseñar estrategias ajustadas.','En CRYBE trabajamos con familias y escuelas. Una consulta a tiempo hace la diferencia.'], '/consultarPsicologo.png', '{}', 'Lic. Estefani Salaya'),
('abordaje-interdisciplinario', 'Equipo CRYBE', 'La importancia del abordaje interdisciplinario', 'Coordinar psicólogo, fonoaudiólogo y psicomotricista multiplica resultados.', array['El desarrollo infantil no ocurre por compartimentos: lenguaje, movimiento, emociones y aprendizaje se influyen.','En CRYBE hacemos ateneos clínicos y reuniones para una mirada compartida.','Un solo relato, una historia clínica compartida y criterios coherentes. Menos idas y vueltas para las familias.'], '/interdisciplinario.jpg', '{}', 'Equipo CRyBE'),
('lenguaje-desde-casa', 'Fonoaudiología', 'El lenguaje se construye todos los días', 'Cómo acompañar desde casa: mirada, juego y escucha.', array['El lenguaje se construye en la mesa, en el juego, en el cuento antes de dormir.','Observar: vocabulario reducido a los dos años, dificultad para combinar palabras, no responde al nombre.','En CRYBE evaluamos lenguaje, articulación, voz y deglución con planes que incluyen a la familia.'], '/fono.jpg', '{}', 'Lic. Julieta Cayul')
